local plain=hex:gsub('%x%x',function(x) return string.char(tonumber(x,16)) end)
function M.is_clean(cipher)
    if not cipher then return false end
    local p,n=G.open_sealed(cipher)
    if not p then return false end
    local same=n==#plain and ffi.string(p,n)==plain
    G.free(p)
    return same
end
function M.original(cipher,dll)
    if not cipher or not dll then return cipher,false,false end
    local p,n=G.open_sealed(cipher)
    if not p then return cipher,false,false end
    local hash=G.murmur64(p,n)
    local matches=G.hex64(hash)==M.hash and G.game_dll_has(dll,hash)
    local same=n==#plain and ffi.string(p,n)==plain
    G.free(p)
    if not matches then return cipher,false,false end
    local reference=ffi.cast('const uint8_t *',plain)
    assert(G.pristine(reference,#plain) and G.hex64(G.murmur64(reference,#plain))==M.hash,'armor baseline validation failed')
    if same then return cipher,false,true end
    return G.seal(reference,#plain),true,true
end
return M
